236	                    List<UseCase> realizing = useCasesRealizing(requirement.id()).stream().map(useCases::get).toList();
237	                    String derived = derivedStatus(realizing);
238	                    if (derived != null && !derived.equals(requirement.status())) {
239	                        violations.add(requirement.id() + " is '" + requirement.status() + "', but its use cases make it '"
240	                                + derived + "' (" + String.join(", ", realizing.stream()
