247	    /** Verified when every use case is Done or Tested, Implemented when every one is at least Implemented. */
248	    private static String derivedStatus(List<UseCase> realizing) {
249	        if (realizing.isEmpty()) {
250	            return null;
251	        }
252	        List<Integer> ranks = new ArrayList<>();
253	        for (UseCase useCase : realizing) {
254	            Integer rank = USE_CASE_PROGRESS.get(useCase.status().toLowerCase());
255	            if (rank == null) {
256	                return null;
257	            }
258	            ranks.add(rank);
