@@ -0,0 +1,51 @@
+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.core.ui.MainLayout;
+import ai.unifiedprocess.petclinic.vet.domain.Vet;
+import ai.unifiedprocess.petclinic.vet.domain.VetRepository;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.router.BeforeEnterEvent;
+import com.vaadin.flow.router.BeforeEnterObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+
+/**
+ * UC-002: View Veterinarians.
+ *
+ * <p>Route {@code /vets}, the target of the "Veterinarians" menu item. The grid
+ * fetches its rows from {@link VetRepository} as the user scrolls (GR-002). The
+ * total is read on entry, so a database failure there fails the navigation and
+ * the error view replaces the screen (UC-002 failure postcondition).
+ */
+@Route(value = "vets", layout = MainLayout.class)
+@PageTitle("Veterinarians")
+public class VeterinariansView extends VerticalLayout implements BeforeEnterObserver {
+
+    private transient VetRepository repository;
+    private int totalVets;
+
+    public VeterinariansView(VetRepository repository) {
+        this.repository = repository;
+
+        Grid<Vet> grid = new Grid<>(Vet.class, false);
+        grid.addColumn(Vet::firstName).setHeader("First name");
+        grid.addColumn(Vet::lastName).setHeader("Last name");
+        grid.addColumn(VeterinariansView::specialtiesOf).setHeader("Specialties");
+        grid.setItems(query -> this.repository.findPage(query.getOffset(), query.getLimit()),
+                query -> this.totalVets);
+        grid.setSizeFull();
+
+        setSizeFull();
+        add(grid);
+    }
+
+    @Override
+    public void beforeEnter(BeforeEnterEvent event) {
+        totalVets = repository.count();
+    }
+
+    private static String specialtiesOf(Vet vet) {
+        return vet.specialties().isEmpty() ? "none" : String.join(", ", vet.specialties());
+    }
+}
