+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+
+import java.util.List;
+import java.util.stream.IntStream;
+
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VETS;
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VET_SPECIALTIES;
+import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+
+/**
+ * UC-002: View Veterinarians.
+ *
+ * <p>The directory is ordered by last name, so the seeded vets appear as
+ * Carter, Douglas, Jenkins, Leary, Ortega, Stevens (row 0 to 5).
+ */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    /** Six vets in V2__seed_reference_data.sql. */
+    private static final int SEEDED_VETS = 6;
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Test
+    @UseCase(id = "UC-002")
+    void veterinariansMenuItemOpensTheDirectory() {
+        navigate(WelcomeView.class);
+
+        SideNavItem menuItem = assertDoesNotThrow(() -> find(SideNavItem.class)
+                        .withPropertyValue(SideNavItem::getLabel, "Veterinarians").single(),
+                "Expected a Veterinarians navigation item");
+        assertEquals("vets", menuItem.getPath(), "Expected the Veterinarians item to lead to /vets");
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void gridShowsFirstNameLastNameAndSpecialtiesOfEveryVeterinarian() {
+        navigate(VeterinariansView.class);
+
+        Grid<?> grid = assertDoesNotThrow(() -> find(Grid.class).single(),
+                "Expected exactly one veterinarians grid");
+        assertEquals("First name", test(grid).getHeaderCell(0));
+        assertEquals("Last name", test(grid).getHeaderCell(1));
+        assertEquals("Specialties", test(grid).getHeaderCell(2));
+        assertEquals(SEEDED_VETS, test(grid).size());
+        assertEquals(List.of("Carter", "Douglas", "Jenkins", "Leary", "Ortega", "Stevens"),
+                IntStream.range(0, SEEDED_VETS).mapToObj(row -> test(grid).getCellText(row, 1)).toList());
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void vetWithoutSpecialtiesIsShownAsNone() {
+        navigate(VeterinariansView.class);
+
+        Grid<?> grid = assertDoesNotThrow(() -> find(Grid.class).single(),
+                "Expected exactly one veterinarians grid");
+        // James Carter holds no specialty and comes first by last name.
+        assertEquals("none", test(grid).getCellText(0, 2));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-002")
+    void specialtiesOfAVetAreListedAlphabetically() {
+        navigate(VeterinariansView.class);
+
+        Grid<?> grid = assertDoesNotThrow(() -> find(Grid.class).single(),
+                "Expected exactly one veterinarians grid");
+        // Linda Douglas was seeded with surgery before dentistry; only an explicit order gives this text.
+        assertEquals("dentistry, surgery", test(grid).getCellText(1, 2));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void rowsAreFetchedFromTheRepositoryPageByPage() {
+        navigate(VeterinariansView.class);
+
+        Grid<?> grid = assertDoesNotThrow(() -> find(Grid.class).single(),
+                "Expected exactly one veterinarians grid");
+        assertInstanceOf(CallbackDataProvider.class, grid.getDataProvider(),
+                "Expected rows to come from a callback that fetches by offset and limit, not a full list");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-003")
+    void directoryOpensWithoutSigningIn() {
+        assertDoesNotThrow(() -> navigate(VeterinariansView.class),
+                "Expected the veterinarians directory to open for an anonymous visitor");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void noVeterinariansRegisteredRendersAnEmptyGrid() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+
+        navigate(VeterinariansView.class);
+
+        Grid<?> grid = assertDoesNotThrow(() -> find(Grid.class).single(),
+                "Expected the veterinarians grid to render without any vets");
+        assertEquals(0, test(grid).size());
+        assertEquals("vets", UI.getCurrent().getInternals().getActiveViewLocation().getPath(),
+                "Expected the view to stay on /vets rather than fall through to an error view");
+    }
+}
